#f7f1e3;border:1px solid #e5d6ae;border-radius:14px;padding:12px 13px;margin-bottom:14px}}.help-block{{padding:12px 0;border-bottom:1px solid #eee7d8}}.help-block:last-child{{border-bottom:0}}.help-block h3{{font-size:13px;margin:0 0 6px;color:#7b612c}}.help-block p{{margin:0;color:#454139}}.help-list{{margin:0;padding-right:18px;color:#454139}}.help-list li{{margin:5px 0}}.help-hint{{display:flex;gap:8px;align-items:flex-start;margin-top:12px;padding:10px 12px;border-radius:12px;background:#f3f2ee;color:#625f58;font-size:11px}}.help-hint .learn-q{{flex:0 0 19px}}.context-learning-note{{display:flex;gap:8px;align-items:center;color:#746b5c;font-size:11px}}.context-learning-note .learn-q{{width:18px;height:18px;font-size:11px}}
